glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
  precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
  in vec4 v_color;
  #if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
  #endif
  uniform ShapeningEff{
    vec2 u_spriteSize;
    float u_amount;
  };
vec4 fTexture2d(sampler2D _texture_, vec2 _uv_)
{
  vec4 _color_ = vec4(1.0);
  vec4 _texture_tmp = texture(_texture_, _uv_);
  #if CC_USE_ALPHA_ATLAS_texture
      _texture_tmp.a *= texture(_texture_, _uv_ + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    _color_.rgb *= (_texture_tmp.rgb * _texture_tmp.rgb);
    _color_.a *= _texture_tmp.a;
  #else
    _color_ *= _texture_tmp;
  #endif
  return  _color_;
}
  void main () {
    vec4 o = vec4(1, 1, 1, 1);
    float amount = u_amount;
    vec2 texSize   = u_spriteSize;
    vec2 fragCoord = v_uv0;
    vec2 texCoord  = fragCoord * texSize;
    float neighbor = amount * -1.0;
    float center   = amount *  4.0 + 1.0;
    float tuvlr = 1.0/texSize.x;
    float tuvud = 1.0/texSize.y;
    vec3 colorC = fTexture2d(texture, fragCoord).rgb * center;
    vec3 colorL = fTexture2d(texture, vec2(fragCoord.x - tuvlr, fragCoord.y)).rgb * neighbor;
    vec3 colorR = fTexture2d(texture, vec2(fragCoord.x + tuvlr, fragCoord.y)).rgb * neighbor;
    vec3 colorU = fTexture2d(texture, vec2(fragCoord.x , fragCoord.y + tuvud)).rgb * neighbor;
    vec3 colorD = fTexture2d(texture, vec2(fragCoord.x , fragCoord.y - tuvud)).rgb * neighbor;
    vec3 colorT = colorC + colorL + colorR + colorU + colorD;
    o = vec4(colorT.rgb, texture2D(texture, fragCoord).a);
    o *= v_color;
    ALPHA_TEST(o);
    #if USE_BGRA
      gl_FragColor = o.bgra;
    #else
      gl_FragColor = o.rgba;
    #endif
  }

